    n = len(grid)
    if k == 1:
        return [min(min(row) for row in grid)]
    best = [float('inf')] * k
    def dfs(r, c, depth, path):
        if depth == k:
            if path < best:
                best[:] = path[:]
            return
        for dr, dc in ((0, 1), (0, -1), (1, 0), (-1, 0)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                path.append(grid[nr][nc])
                dfs(nr, nc, depth + 1, path)
                path.pop()
    for r in range(n):
        for c in range(n):
            if grid[r][c] == best[0]:
                dfs(r, c, 1, [grid[r][c]])
    return best
