    def can_place(grid, r, c, a, b):
        if r + a > H and c + b > W:
            return False
        if r + a <= H and c + b <= W:
            for i in range(r, r + a):
                for j in range(c, c + b):
                    if grid[i][j] != -1:
                        return False
            return True
        if r + a <= H and c + b > W:
            b = W - c
            for i in range(r, r + a):
                for j in range(c, c + b):
                    if grid[i][j] != -1:
                        return False
            return True
        if r + a > H and c + b <= W:
            a = H - r
            for i in range(r, r + a):
                for j in range(c, c + b):
                    if grid[i][j] != -1:
                        return False
            return True
        return False

    def fill(grid, r, c, a, b):
        for i in range(r, r + a):
            for j in range(c, c + b):
                grid[i][j] = 1

    def empty(grid, r, c, a, b):
        for i in range(r, r + a):
            for j in range(c, c + b):
                grid[i][j] = -1

    def find_empty(grid):
        for i in range(H):
            for j in range(W):
                if grid[i][j] == -1:
                    return (i, j)
        return None

    def backtrack(grid, tile_idx):
        pos = find_empty(grid)
        if pos is None:
