    card_pairs = [[] for _ in range(N)]
    for idx, (i, j) in enumerate(pairs):
        card_pairs[i].append(idx)
        card_pairs[j].append(idx)

    # Precompute which pairs are compatible (share a card) with each pair
    pair_compat = [[] for _ in range(len(pairs))]
    for a in range(len(pairs)):
        for b in range(len(pairs)):
            if a != b and pairs[a][0] in pairs[b] or pairs[a][1] in pairs[b]:
                pair_compat[a].append(b)

    memo = {}

    def can_win(mask):
        if mask in memo:
            return memo[mask]

        # Find available pairs (both cards still in mask)
        avail = []
        for idx, (i, j) in enumerate(pairs):
            if (mask >> i) & 1 and (mask >> j) & 1:
                avail.append(idx)

        # No available pairs: current player loses
        if not avail:
            memo[mask] = False
            return False

        # Try each available pair
        for idx in avail:
            i, j = pairs[idx]
            new_mask = mask & ~(1 << i) & ~(1 << j)
            # Opponent loses => current player wins
            if not can_win(new_mask):
                memo[mask] = True
                return True

        memo[mask] = False
        return False

    full_mask = (1 << N) - 1
    if can_win(full_mask):
