    @lru_cache(maxsize=None)
    def dp(pos, prod_primes, sum_digits, tight):
        if pos == L:
            if sum_digits == 0:
                return 0
            p = 1
            for base, exp in prod_primes.items():
                p *= base ** exp
            return 1 if p % sum_digits == 0 else 0
        limit = int(s[pos]) if tight else 9
        total = 0
        for d in range(0, limit + 1):
            new_tight = tight and (d == limit)
            new_sum = sum_digits + d
            if d == 0:
                new_prod = prod_primes
            else:
