import sys

def can_partition(s, target):
    if not s or s[0] == '0' and len(s) > 1:
        pass
    memo = {}
    def dfs(idx, remaining):
        if idx == len(s):
            return remaining == 0
        if (idx, remaining) in memo:
            return memo[(idx, remaining)]
        res = False
        for i in range(idx + 1, len(s) + 1):
            sub = int(s[idx:i])
            if sub <= remaining and dfs(i, remaining - sub):
                res = True
                break
        memo[(idx, remaining)] = res
        return res
    return dfs(0, target)

def punishment_number(n):
    total = 0
    for i in range(1, n + 1):
        sq = i * i
        if can_partition(str(sq), i):
            total += sq
    return total

print(punishment_number(int(sys.stdin.readline())))
